input.command:
cat ~/.openclaw/identity/device.json 2>/dev/null | python3 -m json.tool 2>/dev/null | head -30
echo "---"
cat ~/.openclaw/identity/device-auth.json 2>/dev/null | python3 -m json.tool 2>/dev/null | python3 -c "
import sys, json
d = json.load(sys.stdin)
# Print keys only, not secret values
def scrub(obj, depth=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(x in k.lower() for x in ['token','secret','key','password','credential','auth']):
                print('  '*depth + f'{k}: [REDACTED]')
            else:
                print('  '*depth + f'{k}:')
                scrub(v, depth+1)
    elif isinstance(obj, list):
        print('  '*depth + f'[list of {len(obj)}]')
    else:
        print('  '*depth + repr(obj)[:80])
scrub(d)
" 2>/dev/null || cat ~/.openclaw/identity/device-auth.json | python3 -c "import sys,json; d=json.load(sys.stdin); print(list(d.keys()))"

cat ~/.openclaw/nodes/paired.json | python3 -m json.tool 2>/dev/null | python3 -c "
import sys, json
d = json.load(sys.stdin)
# Show structure with redacted sensitive values
def scrub(obj, depth=0, key=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(x in k.lower() for x in ['token','secret','key','password','credential','privatekey']):
                print('  '*depth + f'{k}: [REDACTED]')
            else:
                print('  '*depth + f'{k}:')
                scrub(v, depth+1, k)
    elif isinstance(obj, list):
        print('  '*depth + f'[{len(obj)} items]')
        for i, item in enumerate(obj[:5]):
            scrub(item, depth+1)
    else:
        val = repr(obj)[:100]
        print('  '*depth + val)
scrub(d)
" 2>/dev/null || cat ~/.openclaw/nodes/paired.json | head -60

# Check devices/paired.json for phone nodes
cat ~/.openclaw/devices/paired.json | python3 -m json.tool 2>/dev/null | python3 -c "
import sys, json
d = json.load(sys.stdin)
def scrub(obj, depth=0):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if any(x in k.lower() for x in ['token','secret','key','password','credential','privatekey']):
                print('  '*depth + f'{k}: [REDACTED]')
            else:
                print('  '*depth + f'{k}:')
                scrub(v, depth+1)
    elif isinstance(obj, list):
        print('  '*depth + f'[{len(obj)} items]')
        for item in obj:
            scrub(item, depth+1)
    else:
        print('  '*depth + repr(obj)[:120])
scrub(d)
" 2>/dev/null | head -80

